package foton; import java.util.UUID; public final class FotonTNTPrimed extends FotonEntity implements org.bukkit.entity.TNTPrimed { public FotonTNTPrimed(UUID id) { super(id); } @Override public org.bukkit.entity.Entity getSource() { String source=Native.entityTntSource(getUniqueId().toString()); try { return source==null?null:FotonEntity.handle(UUID.fromString(source)); } catch (IllegalArgumentException e) { return null; } } }
